static boolean isHighSeason(LocalDate date) {
    Month month = date.getMonth();
    return month == Month.JANUARY
            || month == Month.FEBRUARY
            || month == Month.JULY
            || (month == Month.DECEMBER && date.getDayOfMonth() >= 15)
            || isEasterWeek(date);
}

private static boolean isEasterWeek(LocalDate date) {
    int year = date.getYear();
    return switch (year) {
        case 2027 -> !date.isBefore(LocalDate.of(2027, 3, 21))
                && !date.isAfter(LocalDate.of(2027, 3, 28));
        case 2028 -> !date.isBefore(LocalDate.of(2028, 4, 9))
                && !date.isAfter(LocalDate.of(2028, 4, 16));
        default -> false;
    };
}

