33	    private static NewReservation stay(int roomNumber, String checkIn, String checkOut, int guests, RatePlan plan) {
34	        Guest guest = new Guest("Ana Souza", "ana@example.com", "123.456.789-09");
35	        return new NewReservation(
36	                roomNumber, guest, LocalDate.parse(checkIn), LocalDate.parse(checkOut), guests, plan);
37	    }
38	
39	    private static ErrorCode errorOf(Runnable action) {
40	        return assertThrows(HotelException.class, action::run).errorCode();
41	    }
42	
43	    @Test
44	    void aNewReservationIsPendingWithItsPrice() {
45	        Reservation reservation = service.create(stay(101, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
46	
47	        assertEquals(ReservationStatus.PENDING, reservation.status());
48	        assertEquals(new BigDecimal("749.70"), reservation.price().total());
49	        assertNull(reservation.refund());
50	    }
51	
52	    @Test
53	    void refusesInvalidStays() {
54	        assertEquals(ErrorCode.INVALID_REQUEST,
55	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-10", 2, RatePlan.STANDARD))));
56	        assertEquals(ErrorCode.INVALID_REQUEST,
57	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 0, RatePlan.STANDARD))));
58	        assertEquals(ErrorCode.ROOM_NOT_FOUND,
59	                errorOf(() -> service.create(stay(999, "2027-03-10", "2027-03-12", 2, RatePlan.STANDARD))));
60	        assertEquals(ErrorCode.CAPACITY_EXCEEDED,
61	                errorOf(() -> service.create(stay(101, "2027-03-10", "2027-03-12", 3, RatePlan.STANDARD))));
62	    }
63	
64	    @Test
65	    void aRoomCannotBeBookedTwiceForTheSameNight() {
66	        service.create(stay(201, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
67	
68	        assertEquals(ErrorCode.ROOM_UNAVAILABLE,
69	                errorOf(() -> service.create(stay(201, "2027-03-12", "2027-03-14", 2, RatePlan.STANDARD))));
70	        // the check-out day is free for the next guest, and another room is free on the same nights
71	        service.create(stay(201, "2027-03-13", "2027-03-15", 2, RatePlan.STANDARD));
72	        service.create(stay(202, "2027-03-10", "2027-03-13", 2, RatePlan.STANDARD));
73	    }
